import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';

const API = 'http://localhost:5000/api';

function EmployeeList() {
  const [employees, setEmployees] = useState([]);
  const [search, setSearch] = useState('');
  const [loading, setLoading] = useState(true);
  const navigate = useNavigate();

  useEffect(() => {
    fetchEmployees();
  }, []);

  const fetchEmployees = () => {
    setLoading(true);
    fetch(`${API}/employees`)
      .then(res => res.json())
      .then(data => { setEmployees(data); setLoading(false); })
      .catch(() => setLoading(false));
  };

  const handleDelete = (id, name) => {
    if (!window.confirm(`Xác nhận xoá nhân viên "${name}" (ID: ${id})?`)) return;
    fetch(`${API}/employees/${id}`, { method: 'DELETE' })
      .then(res => res.json())
      .then(data => {
        if (data.status === 'success') {
          alert('Xoá thành công!');
          fetchEmployees();
        } else {
          alert('Lỗi: ' + data.msg);
        }
      })
      .catch(err => alert('Lỗi: ' + err));
  };

  const filtered = employees.filter(e =>
    e.FullName?.toLowerCase().includes(search.toLowerCase()) ||
    e.Department?.toLowerCase().includes(search.toLowerCase()) ||
    String(e.EmployeeID).includes(search)
  );

  return (
    <div className="animate-fade-in">
      <div className="content-card">
        <div className="card-header-custom">
          <h5>👥 Danh Sách Nhân Viên ({filtered.length})</h5>
          <div className="d-flex gap-2">
            <input
              type="text"
              className="form-control form-control-sm"
              placeholder="🔍 Tìm theo tên, phòng ban..."
              style={{width: 250}}
              value={search}
              onChange={e => setSearch(e.target.value)}
            />
            <Link to="/employees/add" className="btn btn-primary-custom btn-sm">
              + Thêm Nhân Viên
            </Link>
          </div>
        </div>
        <div className="table-responsive">
          <table className="table table-custom">
            <thead>
              <tr>
                <th>Mã NV</th>
                <th>Họ Tên</th>
                <th>Phòng Ban</th>
                <th>Chức Vụ</th>
                <th className="text-center">Thao Tác</th>
              </tr>
            </thead>
            <tbody>
              {loading ? (
                <tr>
                  <td colSpan="5" className="text-center py-4 text-muted">
                    ⏳ Đang tải dữ liệu...
                  </td>
                </tr>
              ) : filtered.length === 0 ? (
                <tr>
                  <td colSpan="5" className="text-center py-4 text-muted">
                    Không tìm thấy nhân viên nào
                  </td>
                </tr>
              ) : (
                filtered.map(emp => (
                  <tr key={emp.EmployeeID}>
                    <td><strong>#{emp.EmployeeID}</strong></td>
                    <td>
                      <Link to={`/employees/${emp.EmployeeID}`} className="text-decoration-none fw-semibold">
                        {emp.FullName}
                      </Link>
                    </td>
                    <td>{emp.Department || '—'}</td>
                    <td>{emp.Position || '—'}</td>
                    <td className="text-center">
                      <button
                        className="btn btn-sm btn-outline-primary me-1"
                        onClick={() => navigate(`/employees/${emp.EmployeeID}`)}
                        title="Xem"
                      >👁️</button>
                      <button
                        className="btn btn-sm btn-outline-warning me-1"
                        onClick={() => navigate(`/employees/edit/${emp.EmployeeID}`)}
                        title="Sửa"
                      >✏️</button>
                      <button
                        className="btn btn-sm btn-outline-danger"
                        onClick={() => handleDelete(emp.EmployeeID, emp.FullName)}
                        title="Xoá"
                      >🗑️</button>
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
        </div>
      </div>
    </div>
  );
}

export default EmployeeList;
